"""Shared op definitions: (name, sequential_callable, parallel_callable)."""
import numpy as np
import pandas as pd


def make_df(size, seed=42):
    rng = np.random.default_rng(seed)
    return pd.DataFrame(
        dict(
            a=rng.integers(1, 8, size),
            b=rng.random(size) + 1.0,
        )
    )


def f_row(x):
    return max(x["a"] ** 2, x["b"] ** 2)


def f_col(x):
    return x.max() - x.min()


def f_scalar(x):
    return x ** 2 + 1


def f_series_args(x, power, bias=0):
    return x ** power + bias


def f_group(df):
    dum = 0
    for item in df.b:
        dum += item
    return dum


def f_group_series(s):
    return s.sum()


def f_window(x):
    return len(x) + float(np.nansum(x))


OPS = {}


def register(name):
    def deco(fn):
        OPS[name] = fn
        return fn
    return deco


@register("df_apply_axis1")
def _(df):
    return df.apply(f_row, axis=1), df.parallel_apply(f_row, axis=1)


@register("df_apply_axis0")
def _(df):
    return df.apply(f_col, axis=0), df.parallel_apply(f_col, axis=0)


@register("df_apply_axis_columns")
def _(df):
    return df.apply(f_row, axis="columns"), df.parallel_apply(f_row, axis="columns")


@register("df_apply_row_returns_series")
def _(df):
    g = lambda x: pd.Series({"s": x["a"] + x["b"], "d": x["a"] - x["b"]})
    return df.apply(g, axis=1), df.parallel_apply(g, axis=1)


@register("df_applymap")
def _(df):
    return df.applymap(f_scalar), df.parallel_applymap(f_scalar)


@register("df_map")
def _(df):
    return df.map(f_scalar), df.parallel_map(f_scalar)


@register("series_apply")
def _(df):
    return df.a.apply(f_scalar), df.a.parallel_apply(f_scalar)


@register("series_apply_args")
def _(df):
    return (
        df.a.apply(f_series_args, args=(2,), bias=3),
        df.a.parallel_apply(f_series_args, args=(2,), bias=3),
    )


@register("series_map")
def _(df):
    return df.a.map(f_scalar), df.a.parallel_map(f_scalar)


@register("groupby_apply")
def _(df):
    return (
        df.groupby("a").apply(f_group),
        df.groupby("a").parallel_apply(f_group),
    )


@register("groupby_col_apply")
def _(df):
    return (
        df.groupby("a").b.apply(f_group_series),
        df.groupby("a").b.parallel_apply(f_group_series),
    )


@register("rolling_apply_raw_true")
def _(df):
    return (
        df.b.rolling(4).apply(f_window, raw=True),
        df.b.rolling(4).parallel_apply(f_window, raw=True),
    )


@register("rolling_apply_raw_false")
def _(df):
    return (
        df.b.rolling(4).apply(f_window, raw=False),
        df.b.rolling(4).parallel_apply(f_window, raw=False),
    )


@register("expanding_apply_raw_true")
def _(df):
    return (
        df.b.expanding().apply(f_window, raw=True),
        df.b.expanding().parallel_apply(f_window, raw=True),
    )


@register("groupby_rolling_apply")
def _(df):
    return (
        df.groupby("a").b.rolling(2).apply(f_window, raw=True),
        df.groupby("a").b.rolling(2).parallel_apply(f_window, raw=True),
    )


@register("groupby_expanding_apply")
def _(df):
    return (
        df.groupby("a").b.expanding().apply(f_window, raw=True),
        df.groupby("a").b.expanding().parallel_apply(f_window, raw=True),
    )

