import glob, os, sys, warnings
warnings.simplefilter("ignore")
import numpy as np, pandas as pd
import pandarallel.core as core
from pandarallel import pandarallel

_orig_create = core.create_temp_file


def create_temp_file(prefix):
    # embed creating pid in the file name, no extra I/O
    return _orig_create(prefix + "pid%d_" % os.getpid())


core.create_temp_file = create_temp_file

pandarallel.initialize(nb_workers=2, progress_bar=True, use_memory_fs=True, verbose=0)
df = pd.DataFrame(dict(a=np.arange(1000) + 1, b=np.arange(1000) + 1.0))


class Boom(Exception):
    pass


def bad_group(g):
    raise Boom("boom")


sys.stderr.write("MASTER pid=%d\n" % os.getpid())
nleak = 0
for i in range(60):
    before = set(glob.glob("/dev/shm/pandarallel*"))
    try:
        df.groupby("a").parallel_apply(bad_group)
        o = "no-raise"
    except Exception as e:
        o = type(e).__name__
    after = set(glob.glob("/dev/shm/pandarallel*"))
    leaked = sorted(after - before)
    if leaked:
        nleak += 1
        sys.stderr.write(
            "iter %d outcome=%s LEAKED %s\n"
            % (i, o, [os.path.basename(f) for f in leaked])
        )
        for f in leaked:
            try:
                os.unlink(f)
            except OSError:
                pass
sys.stderr.write("total leaking iterations: %d\n" % nleak)
